CREATE OR REPLACE FUNCTION public.activate_free_plan(p_user_id uuid, p_society uuid, p_tower uuid, p_block uuid, p_flat text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_existing RECORD;
    v_free_plan_id UUID;
    v_sub RECORD;
    v_eligibility JSONB;
BEGIN
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'User ID required');
    END IF;

    SELECT s.subscription_id, s.plan_id, p.plan_code, s.status
    INTO v_existing
    FROM "SSP_Subscription" s
    JOIN "SSP_Subscription_Plan" p ON p.plan_id = s.plan_id
    WHERE s.society = p_society
      AND COALESCE(s.tower::text, '∅') = COALESCE(p_tower::text, '∅')
      AND COALESCE(s.block::text, '∅') = COALESCE(p_block::text, '∅')
      AND upper(trim(s.flat_number)) = upper(trim(p_flat))
      AND s.status IN ('trial', 'active')
      AND (s.end_date IS NULL OR s.end_date > NOW())
    ORDER BY s.created_at DESC LIMIT 1;

    IF v_existing.subscription_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', TRUE, 'already_active', TRUE,
            'subscription_id', v_existing.subscription_id,
            'plan_code', v_existing.plan_code,
            'status', v_existing.status
        );
    END IF;

    v_eligibility := public.can_subscribe(p_user_id, p_society, p_tower, p_block, p_flat);
    IF NOT COALESCE((v_eligibility ->> 'allowed')::boolean, FALSE) THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', COALESCE(v_eligibility ->> 'reason', 'Not eligible'));
    END IF;

    SELECT plan_id INTO v_free_plan_id FROM "SSP_Subscription_Plan"
    WHERE plan_code = 'FREE' AND is_active = TRUE;

    INSERT INTO "SSP_Subscription"
        (society, tower, block, flat_number, owner_society_user,
         plan_id, status, start_date, end_date, auto_renew)
    VALUES
        (p_society, p_tower, p_block, p_flat, p_user_id,
         v_free_plan_id, 'active', NOW(), NULL, FALSE)
    RETURNING * INTO v_sub;

    RETURN jsonb_build_object(
        'success', TRUE, 'already_active', FALSE,
        'subscription_id', v_sub.subscription_id,
        'plan_code', 'FREE', 'status', 'active',
        'start_date', v_sub.start_date
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_my_subscription(p_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user RECORD;
    v_sub RECORD;
    v_cancel_mode TEXT;
    v_already BOOLEAN;
BEGIN
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'User ID required');
    END IF;

    SELECT society, tower, block, unit_flat_number INTO v_user
    FROM "SSP_Society_User" WHERE user_id = p_user_id LIMIT 1;

    IF v_user.society IS NULL OR v_user.unit_flat_number IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Your flat is not configured.');
    END IF;

    SELECT * INTO v_sub FROM "SSP_Subscription"
    WHERE society = v_user.society
      AND COALESCE(tower::text, '∅') = COALESCE(v_user.tower::text, '∅')
      AND COALESCE(block::text, '∅') = COALESCE(v_user.block::text, '∅')
      AND upper(trim(flat_number)) = upper(trim(v_user.unit_flat_number))
    ORDER BY created_at DESC LIMIT 1;

    IF v_sub.subscription_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'No subscription found for this flat.');
    END IF;

    IF v_sub.owner_society_user IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Only the subscription owner can cancel.');
    END IF;

    v_already := (v_sub.cancelled_at IS NOT NULL) OR (v_sub.status = 'cancelled');

    IF v_already THEN
        RETURN jsonb_build_object(
            'success', TRUE, 'already_cancelled', TRUE,
            'subscription_id', v_sub.subscription_id,
            'cancel_mode', CASE WHEN v_sub.end_date IS NULL THEN 'IMMEDIATE' ELSE 'END_OF_PERIOD' END,
            'access_until', v_sub.end_date,
            'auto_renew', v_sub.auto_renew,
            'cancelled_at', v_sub.cancelled_at
        );
    END IF;

    IF v_sub.status IN ('expired', 'refunded', 'transferred') THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', format('Cannot cancel a subscription with status: %s', v_sub.status));
    END IF;

    IF v_sub.end_date IS NULL THEN
        v_cancel_mode := 'IMMEDIATE';
        UPDATE "SSP_Subscription"
        SET status = 'cancelled', auto_renew = FALSE, cancel_reason = p_reason, cancelled_at = NOW(), updated_at = NOW()
        WHERE subscription_id = v_sub.subscription_id
        RETURNING * INTO v_sub;
    ELSE
        v_cancel_mode := 'END_OF_PERIOD';
        UPDATE "SSP_Subscription"
        SET auto_renew = FALSE, cancel_reason = p_reason, cancelled_at = NOW(), updated_at = NOW()
        WHERE subscription_id = v_sub.subscription_id
        RETURNING * INTO v_sub;
    END IF;

    RETURN jsonb_build_object(
        'success', TRUE, 'already_cancelled', FALSE,
        'subscription_id', v_sub.subscription_id,
        'cancel_mode', v_cancel_mode,
        'access_until', v_sub.end_date,
        'auto_renew', v_sub.auto_renew,
        'cancelled_at', v_sub.cancelled_at
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.transfer_accept(p_user_id uuid, p_transfer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_transfer RECORD;
    v_old_sub RECORD;
    v_recipient RECORD;
    v_new_sub RECORD;
BEGIN
    IF p_user_id IS NULL OR p_transfer_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Missing parameters');
    END IF;

    SELECT * INTO v_transfer FROM "SSP_Subscription_Transfer"
    WHERE transfer_id = p_transfer_id;

    IF v_transfer.transfer_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Transfer not found');
    END IF;

    IF lower(v_transfer.status) != 'pending' THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', format('Cannot accept transfer with status: %s', v_transfer.status));
    END IF;

    IF v_transfer.expires_at IS NOT NULL AND v_transfer.expires_at < NOW() THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Transfer has expired');
    END IF;

    IF v_transfer.to_society_user IS DISTINCT FROM p_user_id THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Only the designated recipient can accept this transfer');
    END IF;

    SELECT * INTO v_old_sub FROM "SSP_Subscription"
    WHERE subscription_id = v_transfer.subscription_id;

    IF v_old_sub.subscription_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Original subscription not found');
    END IF;

    SELECT society, tower, block, unit_flat_number INTO v_recipient
    FROM "SSP_Society_User" WHERE user_id = p_user_id LIMIT 1;

    IF v_transfer.transfer_type = 'MEMBER' THEN
        UPDATE "SSP_Subscription"
        SET owner_society_user = p_user_id, updated_at = NOW()
        WHERE subscription_id = v_old_sub.subscription_id
        RETURNING * INTO v_new_sub;

    ELSIF v_transfer.transfer_type = 'GIFT' THEN
        UPDATE "SSP_Subscription"
        SET
            society = v_recipient.society,
            tower = v_recipient.tower,
            block = v_recipient.block,
            flat_number = v_recipient.unit_flat_number,
            owner_society_user = p_user_id,
            updated_at = NOW()
        WHERE subscription_id = v_old_sub.subscription_id
        RETURNING * INTO v_new_sub;

    ELSIF v_transfer.transfer_type = 'SOCIETY' THEN
        UPDATE "SSP_Subscription"
        SET status = 'transferred', updated_at = NOW()
        WHERE subscription_id = v_old_sub.subscription_id;

        INSERT INTO "SSP_Subscription" (
            society, tower, block, flat_number,
            owner_society_user, plan_id, plan_price_id,
            status, start_date, end_date, auto_renew,
            payment_provider, provider_customer_id, provider_subscription_id
        ) VALUES (
            v_transfer.to_society, v_transfer.to_tower, v_transfer.to_block, v_transfer.to_flat_number,
            p_user_id, v_old_sub.plan_id, v_old_sub.plan_price_id,
            'active', v_old_sub.start_date, v_old_sub.end_date, v_old_sub.auto_renew,
            v_old_sub.payment_provider, v_old_sub.provider_customer_id, v_old_sub.provider_subscription_id
        )
        RETURNING * INTO v_new_sub;
    END IF;

    UPDATE "SSP_Subscription_Transfer"
    SET status = 'completed', accepted_at = NOW(), completed_at = NOW()
    WHERE transfer_id = p_transfer_id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'transfer_id', p_transfer_id,
        'new_subscription_id', v_new_sub.subscription_id,
        'status', 'completed'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.transfer_cancel(p_user_id uuid, p_transfer_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_transfer RECORD;
BEGIN
    IF p_user_id IS NULL OR p_transfer_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Missing parameters');
    END IF;

    SELECT * INTO v_transfer FROM "SSP_Subscription_Transfer"
    WHERE transfer_id = p_transfer_id;

    IF v_transfer.transfer_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Transfer not found');
    END IF;

    IF lower(v_transfer.status) != 'pending' THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', format('Cannot cancel transfer with status: %s', v_transfer.status));
    END IF;

    IF v_transfer.from_society_user != p_user_id AND v_transfer.to_society_user != p_user_id THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Only sender or recipient can cancel');
    END IF;

    UPDATE "SSP_Subscription_Transfer"
    SET status = 'cancelled', cancelled_at = NOW(), cancel_reason = p_reason
    WHERE transfer_id = p_transfer_id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'transfer_id', p_transfer_id,
        'status', 'cancelled'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.transfer_request(p_user_id uuid, p_transfer_type text, p_to_society_user uuid DEFAULT NULL::uuid, p_to_society uuid DEFAULT NULL::uuid, p_to_tower uuid DEFAULT NULL::uuid, p_to_block uuid DEFAULT NULL::uuid, p_to_flat_number text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user RECORD;
    v_sub RECORD;
    v_transfer_id UUID;
    v_remaining_days INT;
    v_recipient RECORD;
    v_dest_has_sub BOOLEAN;
    v_transfer_type TEXT;
BEGIN
    IF p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'User ID required');
    END IF;

    v_transfer_type := upper(trim(p_transfer_type));
    IF v_transfer_type NOT IN ('SOCIETY', 'MEMBER', 'GIFT') THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Invalid transfer type');
    END IF;

    SELECT society, tower, block, unit_flat_number INTO v_user
    FROM "SSP_Society_User" WHERE user_id = p_user_id LIMIT 1;

    IF v_user.society IS NULL OR v_user.unit_flat_number IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Your flat is not configured');
    END IF;

    SELECT * INTO v_sub
    FROM "SSP_Subscription"
    WHERE society = v_user.society
      AND COALESCE(tower::text, '∅') = COALESCE(v_user.tower::text, '∅')
      AND COALESCE(block::text, '∅') = COALESCE(v_user.block::text, '∅')
      AND upper(trim(flat_number)) = upper(trim(v_user.unit_flat_number))
      AND lower(status) IN ('trial', 'active')
      AND (end_date IS NULL OR end_date > NOW())
    ORDER BY created_at DESC LIMIT 1;

    IF v_sub.subscription_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'No active subscription to transfer');
    END IF;

    IF v_sub.owner_society_user != p_user_id THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'Only the subscription owner can transfer');
    END IF;

    IF EXISTS (
        SELECT 1 FROM "SSP_Subscription_Transfer"
        WHERE subscription_id = v_sub.subscription_id
          AND lower(status) = 'pending'
          AND (expires_at IS NULL OR expires_at > NOW())
    ) THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'A transfer is already pending for this subscription');
    END IF;

    IF v_transfer_type = 'MEMBER' THEN
        IF p_to_society_user IS NULL THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'to_society_user is required for MEMBER transfer');
        END IF;
        SELECT user_id, society, tower, block, unit_flat_number INTO v_recipient
        FROM "SSP_Society_User" WHERE user_id = p_to_society_user LIMIT 1;
        IF v_recipient.user_id IS NULL THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'Recipient user not found');
        END IF;
        IF v_recipient.society != v_user.society
           OR COALESCE(v_recipient.tower::text,'∅') != COALESCE(v_user.tower::text,'∅')
           OR COALESCE(v_recipient.block::text,'∅') != COALESCE(v_user.block::text,'∅')
           OR upper(trim(v_recipient.unit_flat_number)) != upper(trim(v_user.unit_flat_number))
        THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'Recipient must be on the same flat');
        END IF;
        IF p_to_society_user = p_user_id THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'Cannot transfer to yourself');
        END IF;
    END IF;

    IF v_transfer_type = 'SOCIETY' THEN
        IF p_to_society IS NULL OR p_to_tower IS NULL OR p_to_flat_number IS NULL THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'to_society, to_tower, and to_flat_number are required for SOCIETY transfer');
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM "SSP_Society_User"
            WHERE society = p_to_society
              AND COALESCE(tower::text,'∅') = COALESCE(p_to_tower::text,'∅')
              AND COALESCE(block::text,'∅') = COALESCE(p_to_block::text,'∅')
              AND upper(trim(unit_flat_number)) = upper(trim(p_to_flat_number))
        ) THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'Destination flat has no users');
        END IF;
        SELECT EXISTS (
            SELECT 1 FROM "SSP_Subscription"
            WHERE society = p_to_society
              AND COALESCE(tower::text,'∅') = COALESCE(p_to_tower::text,'∅')
              AND COALESCE(block::text,'∅') = COALESCE(p_to_block::text,'∅')
              AND upper(trim(flat_number)) = upper(trim(p_to_flat_number))
              AND lower(status) IN ('trial', 'active')
              AND (end_date IS NULL OR end_date > NOW())
        ) INTO v_dest_has_sub;
        IF v_dest_has_sub THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'Destination flat already has an active subscription');
        END IF;
    END IF;

    IF v_transfer_type = 'GIFT' THEN
        IF p_to_society_user IS NULL THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'to_society_user is required for GIFT transfer');
        END IF;
        IF p_to_society_user = p_user_id THEN
            RETURN jsonb_build_object('success', FALSE, 'reason', 'Cannot gift to yourself');
        END IF;
    END IF;

    v_remaining_days := CASE
        WHEN v_sub.end_date IS NULL THEN 999999
        ELSE GREATEST(EXTRACT(DAY FROM v_sub.end_date - NOW())::int, 0)
    END;

    INSERT INTO "SSP_Subscription_Transfer" (
        subscription_id, transfer_type,
        from_society, from_tower, from_flat_number, from_society_user,
        to_society, to_tower, to_flat_number, to_society_user,
        remaining_validity_days, status,
        expires_at
    ) VALUES (
        v_sub.subscription_id, v_transfer_type,
        v_sub.society, v_sub.tower, v_sub.flat_number, p_user_id,
        p_to_society, p_to_tower, p_to_flat_number, p_to_society_user,
        v_remaining_days, 'pending',
        NOW() + INTERVAL '7 days'
    )
    RETURNING transfer_id INTO v_transfer_id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'transfer_id', v_transfer_id,
        'status', 'pending',
        'transfer_type', v_transfer_type,
        'remaining_validity_days', v_remaining_days,
        'expires_at', NOW() + INTERVAL '7 days'
    );
END;
$function$
